UPDATE tbl_product_stock_batch
SET quantity = quantity - #{stockNum}
WHERE id = #{id}
  AND product_id = #{productId}
  AND sc_id = #{scId}
  AND quantity >= #{stockNum}

UPDATE tbl_product_stock_batch
SET quantity = quantity + #{stockNum}
WHERE id = #{id}
  AND product_id = #{productId}
  AND sc_id = #{scId}
